use xiom.io;
interface Validator {
  fn validate(&self, input: Str) -> Bool;
  fn error_message(&self) -> Str;
}

type PasswordValidator { min_length: Int; }

fn PasswordValidator.validate(&self, input: Str) -> Bool {
  input.len() >= self.min_length
}

fn PasswordValidator.error_message(&self) -> Str {
  "Password is too short"
}

fn main() -> Int {
  let pw_check = PasswordValidator{ min_length: 8 };
  if pw_check.validate("abc") {
    io.println("Valid!");
  } else {
    io.println(pw_check.error_message());
  };
  if pw_check.validate("abcdefgh") {
    io.println("Valid!");
  } else {
    io.println(pw_check.error_message());
  };
  return 0;
}
